#: How many candidates a composition-fraction ranking reads before it stops.
#: The coefficient is not a column, so the ranking happens in Python and the
#: window is what keeps that bounded.
_FRACTION_RANK_WINDOW = 400


#: `_method_kind` in SQL (PostgreSQL ARE, case-insensitive): a method string that
#: names a calculation or an experiment.
_COMPUTED_METHOD_SQL = (r"\y(DFT|GW|HSE[[:alnum:]_]*|PBE[[:alnum:]_]*|TD-?DFT|B3LYP|ML|machine.learn[[:alnum:]_]*|model|"
                        r"geometric)\y|calculat|comput|predict|estimat")
_MEASURED_METHOD_SQL = r"experiment|measur"

#: Sample.data_type values the sources state.
_EXPERIMENT_SAMPLE = "Experiment"
_CALCULATION_SAMPLE = "Calculation"


def evidence_class_q(kind: str, prefix: str = "") -> Q:
    """Return a Q for Property rows of one evidence class (`prefix`: the path to Property).

    * computed -- a value of a computed source (`vocab.COMPUTED_SOURCES`: they create no
      Samples), of a sample the source states is a calculation, an *_estimate, or a method
      that names a calculation (HOPV's QChem DFT levels, a curated "Computational" row);
    * measured -- a value of a sample the source states is an experiment, a PerovskiteDB
      value whose stated basis (`context.method_basis`) is a measurement on the sample
      (`quality.MEASURED_GAP_BASES`), or a method that states an experiment or measurement;
    * reported -- everything else: the source does not say how the number was obtained (a
      blank method, a PerovskiteDB basis of Literature, Composition or none). The absence of
      a computed marker is not evidence of a measurement.
    """
    p = prefix
    computed = (Q(**{f"{p}data_source__in": vocab.COMPUTED_SOURCES})
                | Q(**{f"{p}sample__data_type": _CALCULATION_SAMPLE})
                | Q(**{f"{p}method__iregex": _COMPUTED_METHOD_SQL})
                | Q(**{f"{p}name__iendswith": "_estimate"}))
    measured = (Q(**{f"{p}sample__data_type": _EXPERIMENT_SAMPLE})
                # containment, not a key lookup: a row stating no basis reads False, not NULL,
                # so that the negation in "reported" keeps it
                | _any_q(Q(**{f"{p}context__contains": {"method_basis": basis}}) for basis in sorted(MEASURED_GAP_BASES))
                | Q(**{f"{p}method__iregex": _MEASURED_METHOD_SQL}))
    if kind == "computed":
        return computed
    if kind == "measured":
        return measured & ~computed
    return ~computed & ~measured


def _any_q(qs) -> Q:
    import functools
    import operator
    return functools.reduce(operator.or_, list(qs))


def evidence_kind_expr(prefix: str = ""):
    """Return `evidence_class_q` as one annotation: 'computed', 'measured' or 'reported'."""
    return Case(When(evidence_class_q("computed", prefix), then=Value("computed")),
                When(evidence_class_q("measured", prefix), then=Value("measured")),
                default=Value("reported"), output_field=CharField())


def evidence_kind_of(prop) -> str:
    """Return the evidence class of one loaded Property (its sample is read when linked)."""
    sample = getattr(prop, "sample", None) if getattr(prop, "sample_id", None) else None
    data_type = getattr(sample, "data_type", None)
    if (prop.data_source in vocab.COMPUTED_SOURCES or data_type == _CALCULATION_SAMPLE
            or (prop.name or "").lower().endswith("_estimate") or _method_kind(prop.method) == "computed"):
        return "computed"
    if (data_type == _EXPERIMENT_SAMPLE or (prop.context or {}).get("method_basis") in MEASURED_GAP_BASES
            or _method_kind(prop.method) == "measured"):
        return "measured"
    return "reported"


def _extreme_property_subquery(name: str, *, how: str = "max", q: Optional[Q] = None, **bounds):
    """Return a subquery for the material's highest or lowest imported value of one property.

    An ascending ranking ("the narrowest recorded band gap") uses the minimum of
    each material's own rows: a record carrying 2.40, 1.55 and 1.95 eV ranks at 1.55.
    """
    from materials.models import Property as _P

    names = [n for n, _ in PROPERTY_FAMILIES[_FAMILY_OF[name]]] if name in _FAMILY_OF else [name]
    scales = _name_scales(names) if len(names) > 1 else {}
    if scales is None:
        names, scales = [name], {}
    # One quantity stored under several names (a `PROPERTY_FAMILIES` entry) is ranked over
    # all of them, each converted to the ranked name's unit, so the reported value is in that
    # unit.
    own = scales.get(name, 1.0) if scales else 1.0
    value = (Case(*[When(name=n, then=F("value") * (own / k)) for n, k in scales.items()], output_field=FloatField())
             if scales else F("value"))
    aggregate = Min(value) if how == "min" else Max(value)
    rows = (_P.objects.filter(q or Q(), material=OuterRef("pk"), name__iexact=name, value__isnull=False,
                              **IMPORTED_ONLY, **bounds) if len(names) == 1 else
            _P.objects.filter(q or Q(), material=OuterRef("pk"), name__in=names, value__isnull=False,
                              **IMPORTED_ONLY, **bounds))
    # A suspect value never ranks a material (quality.eligible_properties, before the aggregate).
    rows = eligible_properties(rows)
    return Subquery(rows.values("material").annotate(m=aggregate).values("m")[:1], output_field=FloatField())


def _max_property_subquery(name: str, **bounds):
    """Return a correlated subquery for the material's highest imported value of one property.

    A correlated subquery reads each material's own rows through the
    `(material_id, name)` index; `Max("properties__value", filter=...)` would join
    Material to the whole property table and group it to order the few rows returned.
    """
    from materials.models import Property as _P

    return Subquery(
        eligible_properties(_P.objects.filter(material=OuterRef("pk"), name__iexact=name,
                                              **IMPORTED_ONLY, **bounds))
        .values("material").annotate(m=Max("value")).values("m")[:1],
        output_field=FloatField(),
    )


def _as_float(raw):
    """Return the bound as a float, or None when absent or unparseable."""
    if raw is None:
        return None
    try:
        return float(raw)
    except (TypeError, ValueError):
        return None


def _range_exists(model, lookups, lo, hi, field="value", q: Optional[Q] = None):
    """Return `Exists` for "this material owns an imported row inside the range".

    All conditions sit in one subquery, so they hold of the same row, as in
    `filter(**{"properties__a": x, "properties__b": y})`, without the join and
    de-duplication that form makes PostgreSQL build.
    """
    rows = dict(lookups)
    rows["created_by__isnull"] = True
    if lo is not None:
        rows[f"{field}__gte"] = lo
    if hi is not None:
        rows[f"{field}__lte"] = hi
    qs = model.objects.filter(q or Q(), material=OuterRef("pk"), **rows)
    # A suspect value does not put a material inside a window; filtered inside the
    # same subquery, so it applies to the same row (quality.eligible_properties).
    if model._meta.model_name == "property":
        qs = eligible_properties(qs)
    elif model._meta.model_name == "device":
        qs = eligible_devices(qs)
    return Exists(qs)


def _device_metric_presence(materials, filter_params):
    """Narrow `materials` by cell metrics that must be recorded or recorded nowhere.

    `require_device_metrics` and `exclude_device_metrics` are each read on an imported,
    eligible solar cell. Eligibility is inside the subquery: a Jsc on a suspect cell neither
    satisfies "with a recorded Jsc" nor removes the material from "without a recorded Jsc"."""
    from materials.models import Device as _Device

    def cells_with(column):
        return Exists(eligible_devices(_Device.objects.filter(
            material=OuterRef("pk"), created_by__isnull=True,
            device_type__iexact="Solar cell", **{f"{column}__isnull": False})))

    for column in filter_params.get("exclude_device_metrics", ()):
        materials = materials.exclude(cells_with(column))
    for column in filter_params.get("require_device_metrics") or ():
        materials = materials.filter(cells_with(column))
    return materials


def _has_eligible_property(**lookups) -> Q:
    """Return a `Material` filter: owns one imported, eligible property row matching every lookup.

    Evaluated through `quality.material_ids_with`, a subquery on the property side, so a
    suspect value neither admits the material nor drops it on account of an unrelated value."""
    from materials.models import Property as _P
    from materials.services.quality import material_ids_with
    return Q(pk__in=material_ids_with(_P.objects.filter(**IMPORTED_ONLY, **lookups)))


def apply_range_filters(materials, filter_params):
    """Narrow `materials` by every numeric bound in `filter_params`.

    Each bound is its own `Exists` subquery. An OR across two multi-valued
    relations written as a join (`Q(devices__...) | Q(properties__...)` with
    `.distinct()`) makes PostgreSQL join Device to Property and de-duplicate the
    product, which is far slower; subqueries aggregate each
    relation separately and cannot duplicate a parent row.
    """
    from materials.models import Device as _Dev, Property as _Prop

    # "Measured values only": estimates and computed rows do not qualify a material.
    measured = evidence_class_q("measured") if filter_params.get("measured_only") else None
    for key, kind, lookups in _RANGE_FILTERS:
        lo = _as_float(filter_params.get(f"{key}_min"))
        hi = _as_float(filter_params.get(f"{key}_max"))
        if lo is None and hi is None:
            continue
        if kind == "pce":
            # PCE is a Solar-cell Device.pce (PerovskiteDB) or a pce_estimate
            # property: HCEP organic-PV molecules have no device rows.
            # A suspect device (DeviceQualityIssue) never qualifies a material.
            cells = _range_exists(_Dev, {"device_type__iexact": "Solar cell"}, lo, hi, field="pce",
                                  q=eligible_device_q())
            materials = materials.filter(
                cells if measured is not None
                else cells | _range_exists(_Prop, {"name__iexact": "pce_estimate"}, lo, hi))
        elif filter_params.get(f"{key}_stat") in ("max", "min"):
            # The window holds the record's highest (or lowest) value, not any
            # one of them: "ZT values that peak between 1 and 2". A record whose
            # peak is inside has a value inside: that indexed test first, so the
            # per-record aggregate runs only on the survivors.
            materials = materials.filter(_range_exists(_Prop, lookups, lo, hi, q=measured))
            aggregate = Max("value") if filter_params[f"{key}_stat"] == "max" else Min("value")
            extreme = Subquery(
                eligible_properties(
                    _Prop.objects.filter(measured or Q(), material=OuterRef("pk"), created_by__isnull=True,
                                         value__isnull=False, **lookups))
                .values("material").annotate(m=aggregate).values("m")[:1],
                output_field=FloatField())
            label = f"_window_{key}"
            materials = materials.annotate(**{label: extreme})
            if lo is not None:
                materials = materials.filter(**{f"{label}__gte": lo})
            if hi is not None:
                materials = materials.filter(**{f"{label}__lte": hi})
        else:
            materials = materials.filter(
                _range_exists(_Prop, lookups, lo, hi, q=measured))

    # A lone lower bound, on a different column of the same relation.
    min_t = _as_float(filter_params.get("measurement_temperature_min"))
    if min_t is not None:
        materials = materials.filter(
            _range_exists(_Prop, {"name__iexact": "ZT"}, min_t, None,
                          field="temperature_k"))
    return materials



def exclude_compounds_outside_windows(materials, filter_params, *, population):
    """Apply "whose recorded values all lie between": the condition is on the compound.

    A window alone means "has a recorded value inside it". The corpus stores many
    compounds as several records of one value each (OQMD holds Ba2I4 as six records
    from 3.774 to 4.395 eV), so a material is removed when any record of its compound
    in `population` carries a value outside the window. The compound is the reduced
    formula (Ba2I4 and BaI2 are one), or the formula where no reduced formula is
    stored. `population` is every record the question names before any window is
    applied.
    """
    from materials.models import Property as _Prop

    if not filter_params.get("range_all_within"):
        return materials
    # "Every measured value": a computed value outside the window does not count.
    measured = evidence_class_q("measured") if filter_params.get("measured_only") else Q()
    if filter_params.get("range_scope") == "record":
        # "every value recorded on it": the record's own values only.
        for key, kind, lookups in _RANGE_FILTERS:
            if kind != "property":
                continue
            lo = _as_float(filter_params.get(f"{key}_min"))
            hi = _as_float(filter_params.get(f"{key}_max"))
            if lo is None and hi is None:
                continue
            outside = Q()
            if lo is not None:
                outside |= Q(value__lt=lo)
            if hi is not None:
                outside |= Q(value__gt=hi)
            materials = materials.exclude(Exists(eligible_properties(_Prop.objects.filter(
                outside & measured, material=OuterRef("pk"), created_by__isnull=True,
                value__isnull=False, **lookups))))
        return materials
    population = population.values("pk")
    for key, kind, lookups in _RANGE_FILTERS:
        if kind != "property":
            continue
        lo = _as_float(filter_params.get(f"{key}_min"))
        hi = _as_float(filter_params.get(f"{key}_max"))
        if lo is None and hi is None:
            continue
        outside = Q()
        if lo is not None:
            outside |= Q(value__lt=lo)
        if hi is not None:
            outside |= Q(value__gt=hi)
        # The compounds with any value outside, computed once as a set: a
        # correlated per-row test (an OR across formula and reduced formula)
        # is far slower. Only an eligible value can put a
        # compound outside the window (quality.eligible_properties).
        offending = eligible_properties(_Prop.objects.filter(
            outside & measured, material__in=population, created_by__isnull=True,
            value__isnull=False, **lookups))
        # A molecule is its own compound: its formula names several isomers, so another
        # record of the same formula is not evidence about it.
        molecular = Q(data_source__in=MOLECULAR_FORMULA_SOURCES)
        materials = materials.exclude(
            Q(formula__in=offending.values("material__formula")) & ~molecular)
        materials = materials.exclude(
            molecular & Q(pk__in=offending.values("material_id")))
        materials = materials.exclude(
            Q(reduced_formula__in=offending.exclude(material__reduced_formula="")
              .values("material__reduced_formula"))
            & ~Q(reduced_formula=""))
    return materials


#: "X against R", "relative to R", "with respect to R": R is the reference.
_REFERENCE_LAYER_RE = re.compile(
    r"\b(?:against|relative\s+to|with\s+respect\s+to)\s+(?:the\s+|an?\s+)?"
    r"([A-Za-z0-9][\w\-\.\(\)]*)", re.IGNORECASE)


def _reference_layer_first(layers, question):
    """Order two layers as the question sets them.

    The convention CBO = EA(layer2) - EA(layer1) makes the order the sign of the
    answer. When the question names a reference ("offsets against PCBM"), that
    layer becomes layer1. Stacks of three or more, and questions that name no
    reference ("between A and B"), are returned unchanged.
    """
    layers = list(layers or [])
    if len(layers) != 2:
        return layers
    for match in _REFERENCE_LAYER_RE.finditer(question or ""):
        named = match.group(1).rstrip(".,;:)").lower()
        for index, layer in enumerate(layers):
            if str(layer).strip().lower() == named:
                return [layers[index], layers[1 - index]]
    return layers


class _MedianAgg(Aggregate):
    """Median computed by PostgreSQL over all rows.

    `PERCENTILE_CONT` interpolates between the two middle values for an even count.
    """
    function = "PERCENTILE_CONT"
    name = "median"
    template = "%(function)s(0.5) WITHIN GROUP (ORDER BY %(expressions)s)"
    output_field = FloatField()


class RankedMaterials(NamedTuple):
    """Result of `_rank_by_displayed_pce`: the ranked items and whether the scan was complete."""
    items: list
    #: True when the scan budget stopped the walk before the exact bound did,
    #: so `items` is a prefix of the ranking rather than the ranking.
    truncated: bool
    scanned: int
    budget: int


def _in_chunks(iterable, size):
    """Yield lists of at most `size` from `iterable`, lazily, so callers can stop early."""
    chunk = []
    for item in iterable:
        chunk.append(item)
        if len(chunk) >= size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk


#: `IMPORTED_ONLY` expressed across MaterialEmbedding -> Material: a material with a
#: `created_by` user (none in the deposit) has no vector in the index.
_EMBED_MATERIAL_IMPORTED = {"material__created_by__isnull": True}


def _methods_behind(rows):
    """Return ([(method, n)], number of methods) for the band-gap values a comparison shows.

    Read from the stored rows rather than inferred from `data_source`, because a
    source does not imply a method: MP's rows say the functional is not stated,
    JARVIS's say OptB88vdW or MBJ, and StarryData2's say the study type is unclassified.
    """
    from collections import Counter

    ids = [r.get("id") for r in rows if r.get("id")]
    if not ids:
        # The caller unpacks two values.
        return [], 0
    from materials.models import Property as _P

    counts = Counter()
    # `value__isnull=False`: a row with no number is not one of the values a
    # reader is looking at.
    for row in (eligible_properties(_P.objects.filter(material_id__in=ids, name__iexact="bandgap",
                                                      value__isnull=False, **IMPORTED_ONLY))
                .values("method").annotate(n=Count("id")).order_by()):
        counts[row["method"] or "(no method recorded)"] += row["n"]
    # The total count is returned with the top six so that the caller can state
    # that the list is truncated.
    top = counts.most_common(6)
    return top, len(counts)


def _rank_by_displayed_pce(materials, *, filter_params, max_results, screen=None):
    """Return the exact top-N materials by the PCE the answer displays.

    The SQL maximum over a material's rows is an upper bound on the displayed
    value, because the plausibility screen can only reject rows; ordering by it
    and slicing could promote a material whose best cell is rejected and push a
    rightful one out of the top N. Instead the candidates are walked in
    descending bound order and the walk stops once the next bound cannot beat
    the Nth exact value found, which is exact and reads few rows beyond N.

    The bound covers both sources of a displayed efficiency: device records and
    the `pce_estimate` property (HCEP organic-PV molecules have no device rows).
    """
    # Each source is its own correlated subquery. Two Max() aggregates over
    # different multi-valued relations make PostgreSQL join both before grouping,
    # pairing every device row with every property row of a material; a subquery
    # aggregates each relation on its own.
    from materials.models import Device as _Device, Property as _Property

    device_pce = Subquery(
        eligible_devices(_Device.objects.filter(material=OuterRef("pk"),
                                                device_type="Solar cell",
                                                **IMPORTED_ONLY))
        .values("material").annotate(m=Max("pce")).values("m")[:1],
        output_field=FloatField(),
    )
    property_pce = Subquery(
        eligible_properties(_Property.objects.filter(material=OuterRef("pk"),
                                                     name__in=("pce_estimate", "PCE"),
                                                     **IMPORTED_ONLY))
        .values("material").annotate(m=Max("value")).values("m")[:1],
        output_field=FloatField(),
    )
    # A material with no PCE anywhere cannot appear in this ranking (its bound
    # is -1.0 and `_displayed` returns None), so excluding it before the sort is
    # exact and keeps the sort to the materials that carry a PCE.
    has_cell = Exists(eligible_devices(_Device.objects.filter(
        material=OuterRef("pk"), device_type="Solar cell", pce__isnull=False, **IMPORTED_ONLY)))
    ordered = materials.filter(
        has_cell if filter_params.get("measured_only")
        else has_cell | Exists(eligible_properties(_Property.objects.filter(
            material=OuterRef("pk"), name__in=("pce_estimate", "PCE"),
            value__isnull=False, **IMPORTED_ONLY)))
    ).annotate(
        _pce_bound=Greatest(
            Coalesce(device_pce, Value(-1.0)),
            Coalesce(property_pce, Value(-1.0)),
        )
    ).order_by(F("_pce_bound").desc(nulls_last=True), "formula", "id")

    def _load_chunk(chunk):
        """Attach the champion pool and the PCE properties to a whole chunk in two queries.

        The pool is the query `champion_cell` would run, stored under the
        `to_attr` it recognises, so the screening logic is unchanged.
        """
        if not chunk:
            return {}
        ids = [m.pk for m in chunk]
        # Shared with the comparison tool, so the pool predicate is defined once.
        _attach_champion_pools(chunk)

        best_prop: dict = {}
        if filter_params.get("measured_only"):
            return best_prop  # a model estimate is not a measured cell
        for row in (eligible_properties(_Property.objects
                    .filter(material_id__in=ids,
                            name__in=("pce_estimate", "PCE"),
                            value__isnull=False, **IMPORTED_ONLY))
                    .values("material_id").annotate(m=Max("value"))
                    .order_by()):
            best_prop[row["material_id"]] = row["m"]
        return best_prop

    def _displayed(mat, best_prop):
        """Return the value this material competes on, or None.

        Only a screened champion cell counts. `champion_cell` falls back to the
        unscreened maximum when none of a material's cells survives; that
        fallback is not used here, so a cell rejected as implausible (e.g. a
        stated PCE inconsistent with its own Voc, Jsc and FF) cannot place a material.
        """
        if screen is not None:
            # Conditions the question states: the best cell meeting them, and
            # no estimate or other fallback -- a material with none drops out.
            cell = champion_cell(mat, screen=screen)
            return float(cell.pce) if cell is not None and cell.pce is not None else None
        cell = champion_cell(mat)
        if cell is not None and cell.pce is not None and is_plausible_cell(cell):
            return float(cell.pce)
        value = best_prop.get(mat.pk)
        return float(value) if value is not None else None

    if screen is not None:
        # Only materials with a cell meeting the stated conditions can place;
        # one query here instead of one per material walked.
        from materials.models import Device as _ScreenDevice
        ordered = ordered.filter(Exists(screen.apply(_ScreenDevice.objects.filter(
            material=OuterRef("pk"), device_type="Solar cell", created_by__isnull=True))))
    lo, hi = _pce_window(filter_params)
    kept: list = []
    #: Hard stop so a pathological filter cannot walk the whole corpus. The
    #: exact bound normally halts far sooner; if the budget binds, the result is
    #: a prefix of the exact ranking and is reported as truncated.
    scan_budget = max(200, max_results * 20)
    truncated = False
    scanned = 0
    stop = False
    #: Walked in chunks so the per-material reads can be batched; each chunk is
    #: a prefix of the bound-descending order, so the early stop is unaffected.
    for chunk in _in_chunks(ordered.iterator(chunk_size=200), 50):
        best_prop = _load_chunk(chunk)
        for mat in chunk:
            if scanned >= scan_budget:
                # The budget bound before the exact stop: the ranking is a
                # prefix, and the caller is told so.
                truncated = stop = True
                break
            scanned += 1
            if len(kept) >= max_results:
                bound = getattr(mat, "_pce_bound", None)
                if bound is None or bound <= kept[-1][0]:
                    stop = True
                    break
            value = _displayed(mat, best_prop)
            if value is None:
                continue
            # The window applies to the displayed value, not to any row of the
            # material: a material whose best cell is 30% does not enter a
            # "below 20%" result because it also owns a 15% cell.
            if lo is not None and value < lo:
                continue
            if hi is not None and value > hi:
                continue
            kept.append((value, mat))
            kept.sort(
                key=lambda pair: (-pair[0], pair[1].formula or "", pair[1].id))
            del kept[max_results:]
        if stop:
            break
    # The truncation flag travels in the result structure, so it survives an
    # empty ranking.
    return RankedMaterials(
        items=[mat for _value, mat in kept],
        truncated=truncated,
        scanned=scanned,
        budget=scan_budget,
    )


def _pce_window(filter_params):
    """Return (min, max) PCE from the request; unparseable bounds become None."""
    out = []
    for key in ("pce_min", "pce_max"):
        raw = filter_params.get(key)
        try:
            out.append(float(raw) if raw is not None else None)
        except (TypeError, ValueError):
            out.append(None)
    return out[0], out[1]


_SUBSCRIPT_DIGITS = str.maketrans("₀₁₂₃₄₅₆₇₈₉", "0123456789")


def _malformed_numbers(text: str) -> list:
    """Return the malformed numbers in a formula.

    These are digit-and-point runs that are not one number ("3.0.5", "3.", ".5")
    and numbers that follow no species or closing bracket ("CsPbI3 0.5", "0.5CsPbI3").
    """
    # A number must start with a digit: the group expander does not read ".5" as a multiplier.
    bad = [run for run in re.findall(r"[\d.]+", text) if not re.fullmatch(r"\d+(?:\.\d+)?", run)]
    bad += [m.group(0) for m in re.finditer(r"(?<![A-Za-z)\]\d.])\d+(?:\.\d+)?", text)]
    return bad


def _unpaired_brackets(text: str) -> list:
    """Return ["unpaired bracket"] when the brackets of `text` do not nest in pairs, else []."""
    closing = {")": "(", "]": "["}
    stack = []
    for ch in text:
        if ch in "([":
            stack.append(ch)
        elif ch in closing and (not stack or stack.pop() != closing[ch]):
            return ["unpaired bracket"]
    return ["unpaired bracket"] if stack else []


def _parse_perovskite_composition(composition: str) -> dict:
    """Parse perovskite composition string into A-site, B-site, X-site dicts.

    Handles formats like:
        FAPbI3, MAPbBr3, CsPbI3
        FA0.8Cs0.2PbI3
        FA0.8Cs0.2PbI2.5Br0.5
        FA0.9MA0.1PbI0.8Br0.2
        CsSnI3, MASnBr3
        FA0.8Cs0.2Pb0.5Sn0.5I3
        Cs0.17FA0.83Pb(I0.83Br0.17)3        (parenthesized X-site)
        (CsBr)0.05[FAMAPb(I0.15Br0.85)3]0.95  (bracketed additive notation)

    Returns:
        {"a_site": {...}, "b_site": {...}, "b_site_element": str, "x_site": {...}}
        plus flags for defaulted, unmodeled, unread and malformed input.
    """
    # Subscript digits are digits: "MAPbI₃" is MAPbI3.
    composition = (composition or "").translate(_SUBSCRIPT_DIGITS)
    # Check brackets and numbers on the formula as written: the group expander
    # tolerates an unpaired bracket and rewrites coefficients, so errors such as
    # "CsPb(I3" or "CsPbI3.0.5" would not be visible after expansion.
    malformed_syntax = _unpaired_brackets(composition) + _malformed_numbers(composition)
    # Expand (...) and [...] groups, e.g. (I0.83Br0.17)3 -> I2.49Br0.51, so the
    # site regexes below see each species with its full coefficient.
    try:
        composition = expand_groups(composition)
    except FormulaExpansionLimitError:
        # Refuse rather than parse the unexpanded string, which would drop the
        # group multipliers. Empty sites lead to the same "undefined" decline as
        # the no-halide case (StabilityAnalyzer's r_x <= 0 guard).
        return {
            "a_site": {},
            "b_site": {},
            "b_site_element": "",
            "x_site": {"I": 0.0, "Br": 0.0, "Cl": 0.0},
            "unmodeled_b_site": [],
            "defaulted_a_site": True,
            "defaulted_b_site": True,
            "expansion_rejected": True,
            "unread_species": [],
            "malformed_syntax": malformed_syntax,
        }
    # The site dictionaries cover every species the regexes below scan for.
    a_site = {"FA": 0.0, "MA": 0.0, "EA": 0.0, "BA": 0.0, "PA": 0.0,
              "Cs": 0.0, "Rb": 0.0, "K": 0.0}
    b_site = {"Pb": 0.0, "Sn": 0.0, "Ge": 0.0, "Bi": 0.0}
    x_site = {"I": 0.0, "Br": 0.0, "Cl": 0.0}

    comp = composition.strip()

    # A-site parsing
    # Organic pseudo-cations (FA/MA/EA/BA/PA) are all-caps two-letter tokens,
    # distinct from the elements Ba/Pa; they are matched before the alkalis.
    a_site_ions = [
        ("FA", r"FA(\d*\.?\d*)"),
        ("MA", r"MA(\d*\.?\d*)"),
        ("EA", r"EA(\d*\.?\d*)"),
        ("BA", r"BA(\d*\.?\d*)"),
        ("PA", r"PA(\d*\.?\d*)"),
        ("Cs", r"Cs(\d*\.?\d*)"),
        ("Rb", r"Rb(\d*\.?\d*)"),
        # The lookahead keeps K from matching inside Kr etc.
        ("K", r"K(?![a-z])(\d*\.?\d*)"),
    ]
    # Sum every occurrence: additive notation such as
    # (CsBr)0.05[FAMAPb(I0.15Br0.85)3]0.95 expands to a string carrying Br twice.
    def _sum_occurrences(pattern):
        """Total stoichiometry for a species; None when it is absent."""
        total = 0.0
        found = False
        for match in re.finditer(pattern, comp):
            total += _coefficient(match.group(1))
            found = True
        return total if found else None

    a_total = 0.0
    for ion, pattern in a_site_ions:
        val = _sum_occurrences(pattern)
        if val is not None:
            a_site[ion] = val
            a_total += val

    # Normalize the A-site to sum 1. `defaulted_a_site` marks that no modelled
    # A-cation was found and FA is a placeholder; tools check the flag first
    # (see `perovskite_model_refusal`).
    defaulted_a_site = a_total <= 0
    if a_total > 0:
        for k in a_site:
            a_site[k] /= a_total
    else:
        a_site["FA"] = 1.0  # default

    # B-site parsing
    # Pb, Sn, Ge (halide perovskite B-site) and Bi (Bi-based and double
    # perovskites such as Cs2AgBiBr6).
    b_patterns = [
        ("Pb", r"Pb(\d*\.?\d*)"),
        ("Sn", r"Sn(\d*\.?\d*)"),
        ("Ge", r"Ge(\d*\.?\d*)"),
        ("Bi", r"Bi(\d*\.?\d*)"),
    ]
    for ion, pattern in b_patterns:
        val = _sum_occurrences(pattern)
        if val is not None:
            b_site[ion] = val

    b_total = sum(b_site.values())
    # As for the A-site: Pb is a placeholder when no modelled B-cation is found.
    defaulted_b_site = b_total <= 0
    if b_total > 0:
        for k in b_site:
            b_site[k] /= b_total
    else:
        b_site["Pb"] = 1.0  # default

    # Pick the dominant element for callers that want a single-element string.
    b_site_element = max(b_site, key=b_site.get) if b_total > 0 else "Pb"

    # B-site cations the ABX3 model does not represent
    # Double perovskites (A2BB'X6, e.g. Cs2AgBiBr6, Cs2AgInCl6) carry a second
    # B'-cation that the B-site regex does not capture; ignoring it would
    # evaluate a fictitious ABX3. These are reported so the tools decline, as
    # BandgapPredictor.predict() does. Bi and Sb are trivalent and cannot occupy
    # the divalent B-site of a charge-balanced ABX3 (they form A3B2X9 or
    # A2BB'X6 phases), so they are flagged too, although Bi is still recorded in
    # b_site. None of these symbols occur in standard FA/MA/Cs-Pb/Sn/Ge-I/Br/Cl
    # perovskites.
    _UNMODELED_B = ("Ag", "Au", "Cu", "Na", "In", "Sb", "Bi", "Tl", "Hg", "Pd",
                    "Pt", "Cd", "Zn", "Mn", "Fe", "Ni", "Co")
    unmodeled_b_site = [sym for sym in _UNMODELED_B
                        if re.search(rf"{sym}(?![a-z])", comp)]

    # X-site parsing
    # Match halide stoichiometry: I2.5, Br0.5, Cl1.0, etc.
    # The lookahead keeps "I" from matching inside In or Ir (CsInO3 is not an
    # iodide); analysis_tools uses the same guard.
    i_total = _sum_occurrences(r"I(?![a-z])(\d*\.?\d*)")
    br_total = _sum_occurrences(r"Br(\d*\.?\d*)")
    cl_total = _sum_occurrences(r"Cl(\d*\.?\d*)")

    if i_total is not None:
        x_site["I"] = i_total
    if br_total is not None:
        x_site["Br"] = br_total
    if cl_total is not None:
        x_site["Cl"] = cl_total

    x_total = x_site["I"] + x_site["Br"] + x_site["Cl"]
    if x_total > 0:
        x_site["I"] /= x_total
        x_site["Br"] /= x_total
        x_site["Cl"] /= x_total
    # A formula without a halide keeps all-zero X fractions; StabilityAnalyzer
    # rejects r_x <= 0 and reports the result as undefined.

    # Text that no species pattern read
    # The A-site patterns match letters anywhere, so DMA or EMA would otherwise
    # be read as MA. Remove every consumed token and the stoichiometry
    # characters; anything left (letters, '+', '%', '/', ',', or a '-' and what
    # follows it) was not read, and `perovskite_model_refusal` declines it.
    consumed = re.sub(
        r"FA|MA|EA|BA|PA|Cs|Rb|K(?![a-z])|Pb|Sn|Ge|Bi|I(?![a-z])|Br|Cl|"
        + "|".join(rf"{sym}(?![a-z])" for sym in _UNMODELED_B),
        " ", comp)
    unread_species = re.findall(r"[^()\[\]\d.\s·~]+", consumed)
    if re.search(r"[()\[\]]", comp):
        malformed_syntax.append("unexpanded bracket")

    return {
        "a_site": a_site,
        "b_site": b_site,
        "b_site_element": b_site_element,
        "x_site": x_site,
        "unmodeled_b_site": unmodeled_b_site,
        "unread_species": unread_species,
        "malformed_syntax": malformed_syntax,
        "defaulted_a_site": defaulted_a_site,
        "defaulted_b_site": defaulted_b_site,
        "expansion_rejected": False,
        # Site totals as written, before normalization, for the ABX3
        # stoichiometry check (MA0.5Sn0.5PbI3 would normalize to MAPb0.67Sn0.33I3).
        "site_totals": {"A": a_total, "B": b_total, "X": x_total},
    }


def perovskite_model_refusal(parsed: Dict[str, Any]) -> Optional[str]:
    """Return why a parsed composition is outside the ABX3 model, or None if it is inside.

    Every tool consults this before computing. Reasons, in order:

    * `expansion_rejected` -- group multipliers could not be applied.
    * `unmodeled_b_site` -- a B'-cation the ABX3 model drops (Cs2AgInCl6).
    * `defaulted_a_site` / `defaulted_b_site` -- no modelled species at that
      site, so the parser substituted FA or Pb (e.g. MgCl2).
    * `malformed_syntax` -- unpaired brackets or malformed numbers ("CsPb(I3").
    * `unread_species` -- text no species pattern read (e.g. DMA in Cs0.7DMA0.3PbI3).

    A reason string, rather than an exception, matches the no-halide decline
    that callers already report.
    """
    if parsed.get("expansion_rejected"):
        return (
            "Composition could not be expanded within the parser's limits, so "
            "its site fractions cannot be determined."
        )
    unmodeled = parsed.get("unmodeled_b_site") or []
    if unmodeled:
        return (
            f"Composition contains B-site cation(s) {', '.join(unmodeled)}, which "
            "indicate a double-perovskite or non-ABX3 phase that this ABX3 model "
            "does not represent."
        )
    missing = []
    if parsed.get("defaulted_a_site"):
        missing.append("A-site cation (FA, MA, EA, BA, PA, Cs, Rb or K)")
    if parsed.get("defaulted_b_site"):
        missing.append("B-site cation (Pb, Sn or Ge)")
    if missing:
        return (
            "Composition contains no modelled " + " and no modelled ".join(missing)
            + ", so it is not an ABX3 halide perovskite this model can evaluate."
        )
    malformed = parsed.get("malformed_syntax") or []
    if malformed:
        return (
            "Composition is not a well-formed formula (" + ", ".join(f"'{m}'" for m in malformed)
            + "), so its site fractions cannot be read and it is not evaluated."
        )
    unread = parsed.get("unread_species") or []
    if unread:
        return (
            "Composition contains " + ", ".join(f"'{u}'" for u in unread)
            + ", which the model does not read as an FA, MA, EA, BA, PA, Cs, Rb or K "
            "cation, a Pb, Sn or Ge B-site or an I, Br or Cl halide (dimethylammonium, "
            "for instance, is not methylammonium), so it is not evaluated."
        )
    return None


#: What a predicted band gap is, stated wherever one is reported, so that the
#: estimate is not presented as a stored or citable value.
PREDICTION_NATURE = ("Nature: a model estimate (Vegard interpolation with bowing, from calibrated end "
                     "members), not a measured or database value -- never present it as the compound's "
                     "band gap or as a citable value; stored measurements are the citable ones.")

#: What a tolerance-factor verdict is: a geometric criterion for forming an ABX3
#: structure, not evidence of stability in operation or fitness for a product.
FORMABILITY_NATURE = ("Report t, mu and the verdict as given. The verdict is geometric: whether an "
                      "ABX3 perovskite structure can form. It does not show stability in air, "
                      "moisture, heat, light or operation, or fitness for a product -- if the "
                      "question asks that, say these factors do not settle it.")

#: How far a site total may sit from ABX3's 1 / 1 / 3 and still be that stoichiometry
#: (rounded compositions: Cs0.05FA0.79MA0.16 sums to 1.00, I2.49Br0.51 to 3.00).
_ABX3_SITE_TOLERANCE = {"A": 0.02, "B": 0.02, "X": 0.05}


def abx3_calculation_refusal(parsed: Dict[str, Any]) -> Optional[str]:
    """Return why a band gap, tolerance or octahedral factor cannot be computed, or None.

    Applies `perovskite_model_refusal`, then requires the written site totals to
    be A 1, B 1, X 3: renormalizing other totals would compute another compound.
    Site fractions and charge balance do not use this check.
    """
    refusal = perovskite_model_refusal(parsed)
    if refusal:
        return refusal
    totals = parsed.get("site_totals")
    if not totals:
        return None
    want = {"A": 1.0, "B": 1.0, "X": 3.0}
    if all(abs(totals[k] - want[k]) <= _ABX3_SITE_TOLERANCE[k] for k in want):
        return None
    written = ", ".join(f"{k} {format_coefficient(round(totals[k], 3))}" for k in ("A", "B", "X"))
    meant = _b_site_substitution_meant(parsed)
    return (f"As written the sites total {written}, not ABX3's A 1, B 1, X 3, so this is not "
            "an ABX3 composition the model evaluates (renormalising the sites would compute a "
            "different compound). "
            + (meant or "Check the formula: a B-site substitution is written on the B site, e.g. "
                        "MAPb0.5Sn0.5I3."))


def _b_site_substitution_meant(parsed: Dict[str, Any]) -> str:
    """Suggest the ABX3 formula for a B-site substituent written on the A site, or return "".

    MA0.5Ge0.5PbI3 (A 0.5, B 1.5) is read as MAPb0.5Ge0.5I3. A suggestion is made
    only when one B species carries exactly the excess beside a host at 1, so a
    plainly wrong formula (CsPbI4) gets none.
    """
    totals = parsed.get("site_totals") or {}
    if not totals or abs(totals.get("X", 0) - 3.0) > _ABX3_SITE_TOLERANCE["X"]:
        return ""
    d, e = 1.0 - totals["A"], totals["B"] - 1.0
    # The substituent replaces part of the A site (MA0.5Ge0.5PbI3) or precedes an
    # intact formula (Sn0.5MAPbI3); either way one B species carries the excess.
    if e <= 0.02 or e >= 0.98 or not (abs(d - e) <= 0.02 or abs(d) <= 0.02):
        return ""
    d = e
    raw = {el: f * totals["B"] for el, f in (parsed.get("b_site") or {}).items() if f}
    subs = [el for el, n in raw.items() if abs(n - d) <= 0.02]
    hosts = [el for el, n in raw.items() if abs(n - 1.0) <= 0.02]
    if len(raw) != 2 or len(subs) != 1 or len(hosts) != 1 or subs == hosts:
        return ""
    a = [(el, f) for el, f in (parsed.get("a_site") or {}).items() if f]
    x = [(el, f) for el, f in (parsed.get("x_site") or {}).items() if f]
    formula = ("".join(el if len(a) == 1 else f"{el}{format_coefficient(round(f, 3))}" for el, f in a)
               + f"{hosts[0]}{format_coefficient(round(1 - d, 3))}{subs[0]}{format_coefficient(round(d, 3))}"
               + "".join(f"{el}{format_coefficient(round(3 * f, 3))}" for el, f in x))
    return (f"If the question means replacing {format_coefficient(round(d, 3))} of the {hosts[0]} with {subs[0]}, that "
            f"composition is {formula}: call the tool again with it and say that you did.")


#: Attributes `with_embed_inputs` sets on a material, so that building the text for a
#: batch costs three queries per batch rather than per material. `_build_material_text`
#: reads them when present.
EMBED_PROPS_ATTR = "_embed_props"
EMBED_DEVICES_ATTR = "_embed_devices"
EMBED_FORMS_ATTR = "_embed_forms"
#: How many property groups (one per stored name, unit and method), device types and
#: sample forms the text carries.
EMBED_PROPERTY_SLICE = 12
EMBED_DEVICE_SLICE = 4
EMBED_FORM_SLICE = 3


def _embed_property_groups(material_ids):
    """{material id: [(name, unit, method, phase, n, lo, hi)]}: the public values of the materials.

    Aggregated per stored name, unit, method and stated phase (`context.phase`, so a solution and a
    film PLQY stay apart). Only imported, numeric and eligible values (none under a suspect
    objection), so the text does not depend on the order the rows were written in."""
    from materials.models import Property
    rows = (eligible_properties(Property.objects.filter(material_id__in=material_ids, created_by__isnull=True,
                                                        value__isnull=False))
            .order_by().annotate(_phase=KT("context__phase"))
            .values("material_id", "name", "unit", "method", "_phase")
            .annotate(n=Count("id"), lo=Min("value"), hi=Max("value")))
    out: Dict[int, list] = {}
    for r in rows:
        out.setdefault(r["material_id"], []).append(
            (r["name"] or "", r["unit"] or "", r["method"] or "", r["_phase"] or "", r["n"], r["lo"], r["hi"]))
    return out


def _embed_device_groups(material_ids):
    """{material id: [(device_type, n, lo, hi)]}: eligible devices with a PCE, per device type."""
    from materials.models import Device
    rows = (eligible_devices(Device.objects.filter(material_id__in=material_ids, created_by__isnull=True,
                                                   pce__isnull=False))
            .order_by().values("material_id", "device_type")
            .annotate(n=Count("id"), lo=Min("pce"), hi=Max("pce")))
    out: Dict[int, list] = {}
    for r in rows:
        out.setdefault(r["material_id"], []).append((r["device_type"] or "", r["n"], r["lo"], r["hi"]))
    return out


def _embed_sample_forms(material_ids):
    """{material id: [form]}: the stated sample forms (bulk, film, single crystal, ...)."""
    from materials.models import Sample
    out: Dict[int, list] = {}
    for mid, form in (Sample.objects.filter(material_id__in=material_ids).exclude(form__isnull=True)
                      .exclude(form="").order_by().values_list("material_id", "form").distinct()):
        out.setdefault(mid, []).append(form)
    return out


def with_embed_inputs(materials):
    """Return `materials` as a list with their embedding-text inputs attached (three queries)."""
    materials = list(materials)
    ids = [m.pk for m in materials]
    props, devices, forms = _embed_property_groups(ids), _embed_device_groups(ids), _embed_sample_forms(ids)
    for m in materials:
        setattr(m, EMBED_PROPS_ATTR, props.get(m.pk, []))
        setattr(m, EMBED_DEVICES_ATTR, devices.get(m.pk, []))
        setattr(m, EMBED_FORMS_ATTR, forms.get(m.pk, []))
    return materials


def _embed_value(value) -> str:
    # Three decimals keep at most one significant digit below 0.01 (a resistivity of 1.5e-4 ohm m
    # would read "0.000"), so such values keep four significant digits. Zero prints without a sign:
    # -0.0 and 0.0 compare equal under MIN/MAX, so the sign a group reports would follow row order.
    if value == 0:
        return "0.000"
    if abs(value) < 0.01:
        return _format_measurement(value)
    text = f"{value:.3f}"
    return "0.000" if text == "-0.000" else text


def _format_bandgap(value, *, n_observations=None, lo=None, hi=None) -> str:
    """Render a band gap; shared by every tool that prints one.

    An exact zero is a stored DFT result (2DMatPedia, C2DB, JARVIS) and is
    annotated as "this method reports no gap" rather than "metallic": PBE
    underestimates gaps, and some JARVIS materials hold a non-zero MBJ gap beside
    the zero. When several values exist, pass `n_observations`, `lo` and `hi` to
    state the range; a caller holding one value passes none.
    """
    out = f"bandgap={value:.3f} eV"
    if value == 0.0:
        out += " (this method reports no gap)"
    if n_observations and n_observations > 1 and lo is not None and hi is not None:
        out += f" (lowest of {n_observations} imported values, {lo:.3f}-{hi:.3f} eV)"
    return out


def _build_material_text(material: Material) -> str:
    """Return the text that becomes a material's embedding vector.

    The single definition used by the offline embedding commands and the stored-vector check
    (`stored_vector`, `rebuild_faiss_index --check`). It describes the corpus record from its
    public fields: formula (and the display formula when the source's notation differs), the
    name (a sample label for StarryData2, the only identifier of a formula-less Curated-OLED
    emitter), the source, the classification labels and material family, the lead status, the
    stated sample forms, the eligible values aggregated per stored name, unit, method and stated
    phase (a value under a suspect objection or a not-stated value is left out), the eligible
    devices' efficiencies per device type, and the sanitized description. Notes, raw arrays
    (`source_attributes.cfid`, `context.series`) and list reprs are never included; a blank
    field is left out rather than written as "Unknown".

    Deterministic for the same record: aggregates and sorted labels make the text independent of row
    order and primary keys. `MaterialEmbedding.text_snapshot` holds its first 4000 characters and is
    compared with them, so any change to this function makes every stored vector stale.

    Batch callers pass materials through `with_embed_inputs` first (three queries per batch);
    otherwise the inputs are read for this one material.
    """
    if getattr(material, EMBED_PROPS_ATTR, None) is None:
        ids = [material.pk]
        props, devices, forms = (_embed_property_groups(ids).get(material.pk, []),
                                 _embed_device_groups(ids).get(material.pk, []),
                                 _embed_sample_forms(ids).get(material.pk, []))
    else:
        props, devices, forms = (getattr(material, EMBED_PROPS_ATTR), getattr(material, EMBED_DEVICES_ATTR),
                                 getattr(material, EMBED_FORMS_ATTR))
    formula = _clean_field(material.formula)
    parts = [f"Formula: {formula}"] if formula else []
    display = _clean_field(material.display_formula)
    if display and display != formula:
        parts.append(f"Display formula: {display}")
    name = _clean_field(material.name, max_len=120)
    if name and name != formula:
        label = "Sample label" if (material.data_source or "") in _SAMPLE_LABEL_SOURCES else "Name"
        parts.append(f"{label}: {name}")
    parts.append(f"Source: {_clean_field(material.data_source, max_len=40)}")
    for label, value in (("Chemical class", material.chemical_class), ("Structure type", material.structure_type),
                         ("Crystal system", material.crystal_system), ("Dimensionality", material.dimensionality),
                         ("Morphology", material.morphology), ("Function", material.function),
                         ("Device", material.device), ("Material family", material.material_family)):
        value = _clean_field(value)
        if value:
            parts.append(f"{label}: {value}")
    if material.is_lead_free is not None:
        parts.append(f"Pb-free: {'Yes' if material.is_lead_free else 'No'}")
    forms = sorted({_clean_field(f, max_len=40) for f in forms} - {""},
                   key=lambda f: (f.casefold(), f))[:EMBED_FORM_SLICE]
    if forms:
        parts.append("Sample form: " + ", ".join(forms))
    groups = sorted(props,
                    key=lambda g: (g[0].casefold(), g[0], g[3], g[1], g[2]))[:EMBED_PROPERTY_SLICE]
    prop_lines = []
    for name, unit, method, phase, n, lo, hi in groups:
        # one value when the bounds print alike (equal, or equal after rounding)
        low, high = _embed_value(lo), _embed_value(hi)
        value = low if low == high else f"{low} to {high}"
        unit = f" {_clean_field(unit, max_len=24)}" if unit else ""
        notes = ([f"{n} values"] if n > 1 else []) + ([_clean_field(method, max_len=60)] if method else [])
        label = _clean_field(name, max_len=48) + (f" ({_clean_field(phase, max_len=20)})" if phase else "")
        prop_lines.append(f"{label}: {value}{unit}" + (f" ({'; '.join(notes)})" if notes else ""))
    if prop_lines:
        parts.append("Properties: " + "; ".join(prop_lines))
    device_lines = []
    for device_type, n, lo, hi in sorted(devices,
                                         key=lambda g: (g[0].casefold(), g[0]))[:EMBED_DEVICE_SLICE]:
        low, high = (f"{0.0 if v == 0 else v:.2f}" for v in (lo, hi))
        pce = f"{low}%" if low == high else f"{low} to {high}%"
        device_lines.append(f"{_clean_field(device_type, max_len=48) or 'Device'} PCE {pce} "
                            f"({n} device{'s' if n != 1 else ''})")
    if device_lines:
        parts.append("Device metrics: " + "; ".join(device_lines))
    if material.description:
        sanitized = _sanitize_user_text(material.description, max_len=400)
        if sanitized:
            parts.append(f"Description: {sanitized}")
    return "\n".join(parts)


_INJECTION_PATTERNS = re.compile(
    # Common prompt-injection phrasings, matched case-insensitively.
    r"(?i)(?:"
    # "ignore" / "disregard" / "skip" + (all|prior|previous|above) + (instructions|prompts|rules)
    r"(?:ignore|disregard|skip|bypass)\s+(?:all\s+|the\s+)?(?:prior|previous|above|earlier)\s+(?:instructions?|prompts?|rules?|directives?)"
    # "system override" / "new system rule" / "system_rule"
    r"|(?:system|admin|root)[\s_-]+(?:override|rule|prompt|instruction|directive)"
    # XML-style fake delimiter injection
    r"|<\s*/?\s*(?:system|context|instruction|prompt|user|assistant)\s*[/>]?"
    # "new system" / "new instruction"
    r"|new\s+(?:system|rule|instruction|directive)"
    # "forget everything/prior/all/role/identity"
    r"|forget\s+(?:everything|prior|all|your\s+role|your\s+identity|your\s+instructions?)"
    # "from now on you are/will": common jailbreak opener
    r"|from\s+now\s+on\s+you\s+(?:are|will|must|should)"
    # "act as" only with role-impersonation targets, so chemistry phrases such as
    # "acts as a buffer/stabilizer/dopant" in material descriptions are not redacted.
    r"|(?:act\s+as|pretend\s+to\s+be|roleplay\s+as|behave\s+like)\s+(?:a|an|the)?\s*"
    r"(?:human|user|assistant|AI|chatbot|model|expert|system|developer|admin|root|"
    r"ChatGPT|GPT|Claude|LLM|language\s+model)"
    # Markers like "[INST]" / "###SYSTEM" / "<|im_start|>": model-template leaks
    r"|\[\s*(?:INST|SYS|SYSTEM|ASSISTANT)\s*\]"
    r"|###+\s*(?:SYSTEM|INSTRUCTION|PROMPT|RULE)"
    r"|<\|(?:im_start|im_end|system|user|assistant)\|>"
    # "respond only with" only with instruction-shaped targets (yes/no, JSON, format),
    # so phrasing such as "respond only with verified data" is not matched.
    r"|respond\s+only\s+with\s+(?:yes|no|true|false|JSON|the\s+following|a\s+single)"
    r"|output\s+only\s+(?:yes|no|true|false|JSON|the\s+following|a\s+single)"
    r")"
)


def _sanitize_user_text(text: str, max_len: int = 400) -> str:
    """Remove prompt-injection patterns and hidden characters from user text.

    The text is NFKC-normalized; control characters, Unicode format characters
    (zero-width, bidi controls and overrides, BOM) and line/paragraph separators
    are dropped; instruction-like phrases are replaced by a marker; the result
    is truncated to `max_len`.
    """
    if not text:
        return ""
    # NFKC normalize: collapses full-width forms, deprecated compat chars, etc.
    import unicodedata
    text = unicodedata.normalize("NFKC", text)
    # Drop ASCII control characters except whitespace
    text = "".join(c for c in text if c == "\n" or c == "\t" or ord(c) >= 0x20)
    # Drop all Unicode format characters (category Cf): soft hyphen, zero-width
    # characters, bidi controls, word joiner, BOM. Cf excludes the Zl/Zp
    # separators, which the explicit list below removes.
    text = "".join(c for c in text if unicodedata.category(c) != "Cf")
    # Drop Unicode hidden / spoofing chars
    _HIDDEN_CHARS = (
        "​‌‍‎‏"  # zero-width + LTR/RTL marks
        "‪‫‬‭‮"  # bidi embeddings and overrides
        "  "                    # line/paragraph separator
        "⁠﻿"                    # word-joiner + BOM
    )
    text = "".join(c for c in text if c not in _HIDDEN_CHARS)
    # Neutralize injection patterns with a marker so the LLM sees the
    # attempt but knows to ignore it.
    text = _INJECTION_PATTERNS.sub("[redacted-instruction-like-text]", text)
    return text[:max_len]


def _compound_deposits_coordinates(data) -> bool:
    """Whether a resolved cousin's compound has a public record with deposited coordinates."""
    formula = (data or {}).get("formula") if isinstance(data, dict) else None
    if not formula:
        return False
    return _materials_of_compound(formula).filter(deposited_coordinates_q()).exists()


def cousin_matches_constraints(
    data,
    *,
    lead_free: bool = False,
    chemical_class: str = "",
    structure_type: str = "",
    dimensionality: str = "",
    bandgap_window: Optional[Tuple[float, float]] = None,
) -> bool:
    """Return whether one conceptual cousin satisfies the query's constraints.

    Shared by the agent tool and the pre-router so both apply the same filter.
    `data` is None (or has a "(not in DB" data_source) for a cousin absent from
    the corpus; such a cousin cannot be checked and is rejected whenever any
    constraint is active.
    """
    if bandgap_window is not None:
        # A cousin with no band gap on record cannot satisfy a stated window.
        gap = data.get("bandgap") if data else None
        if gap is None or not (bandgap_window[0] <= float(gap) <= bandgap_window[1]):
            return False
    if not (lead_free or chemical_class or structure_type or dimensionality):
        return True
    if data is None:
        return False
    if "(not in DB" in str(data.get("data_source", "")):
        return False
    # Unknown (None) does not satisfy a Pb-free constraint.
    if lead_free and data.get("is_lead_free") is not True:
        return False
    # A blank categorical field means "not curated", not a mismatch; only a
    # value that contradicts the constraint rejects the cousin (structure_type,
    # in particular, is blank on many records).
    if _contradicts(data.get("chemical_class"), chemical_class, exact=True):
        return False
    if _contradicts(data.get("structure_type"), structure_type, exact=False):
        return False
    if _contradicts(data.get("dimensionality"), dimensionality, exact=True):
        return False
    return True


def _contradicts(value, required: str, *, exact: bool) -> bool:
    """Return True when a curated field disagrees with the constraint.

    An empty `required` or a blank `value` is not a contradiction.
    """
    if not required:
        return False
    value = (value or "").strip()
    if not value:
        return False
    return value.lower() != required.lower() if exact \
        else required.lower() not in value.lower()


def _escape_braces(text: str) -> str:
    """Escape { and } for LangChain's f-string prompt templates.

    The system message is parsed as an f-string template, so an unescaped brace
    in interpolated text would act as a placeholder (e.g. "{input}" would insert
    the raw user question) or make template construction fail. Applied where
    values are interpolated, so every value is covered.
    """
    return str(text).replace("{", "{{").replace("}", "}}")


#: Blank-rendering characters that are not in Cc/Cf/Mn.
#:
#: The injection fence detects on an NFKC fold with Cc/Cf/Mn removed, which covers soft hyphen,
#: zero-width space, combining grapheme joiner and variation selectors. The characters below render
#: as nothing or as blank yet carry a letter/symbol category, so they split a trigger token for the
#: regex while a human or a model still reads the word:
#:     U+115F HANGUL CHOSEONG FILLER      Lo
#:     U+1160 HANGUL JUNGSEONG FILLER     Lo
#:     U+3164 HANGUL FILLER               Lo
#:     U+FFA0 HALFWIDTH HANGUL FILLER     Lo   (NFKC folds to U+1160)
#:     U+2800 BRAILLE PATTERN BLANK       So
#:
#: A curated list rather than a category rule: Unicode has no "is invisible" property, and category
#: and East Asian width classify U+3164 like an ordinary Hangul letter. Redacting every character
#: that breaks a token is no substitute, since "i!gnore" must stay as written.
_ZERO_WIDTH_NON_CATEGORY = frozenset("\u115f\u1160\u3164\uffa0\u2800")


def _clean_field(value: Any, max_len: int = 120) -> str:
    """Sanitize a short user-writable field before it enters the LLM context.

    Covers formula, classification fields, property names, units and device types,
    which reach both the embedding text and the prompt context. Clean text is
    NFC-normalized to preserve units such as mA/cm² and K⁻¹; injection is detected
    on the NFKC fold, so full-width homoglyphs are caught, and redacted there.
    The result is one line, at most `max_len` characters.
    """
    if value is None:
        return ""
    text = str(value)
    if not text:
        return ""
    import unicodedata

    def _keep(c: str) -> bool:
        # Keep whitespace (collapsed later); drop control (Cc) and format (Cf)
        # characters by category: soft hyphen, zero-width, bidi, BOM, etc.
        if c in " \t\n":
            return True
        cat = unicodedata.category(c)
        if cat == "Cc" or cat == "Cf":
            return False
        return ord(c) >= 0x20

    def _strip_collapse(s: str) -> str:
        # Drop control/format characters and collapse all whitespace to single
        # spaces: a newline could forge a line in the line-based context text,
        # and a whitespace-only field becomes "" so the 'Unknown' fallback applies.
        return " ".join("".join(c for c in s if _keep(c)).split())

    # Detect injection after removing hidden characters and combining marks, so a
    # character inserted inside a trigger word cannot hide it, and on the NFKC
    # fold, so full-width homoglyphs are caught.
    fold = unicodedata.normalize("NFKC", text)
    fold = " ".join(
        "".join(
            c for c in fold
            if c in " \t\n" or (
                unicodedata.category(c) not in ("Cc", "Cf", "Mn")
                and c not in _ZERO_WIDTH_NON_CATEGORY
            )
        ).split()
    )
    if _INJECTION_PATTERNS.search(fold):
        # Redact on `fold`, where the trigger word is contiguous; redacting the
        # raw text would leave a mark-split word in place.
        return _INJECTION_PATTERNS.sub("[redacted-instruction-like-text]", fold)[:max_len]
    # Clean path: NFC keeps super/subscript units (mA/cm², K⁻¹) unchanged.
    return _strip_collapse(unicodedata.normalize("NFC", text))[:max_len]


def _sanitize_block(text: Any, max_len: int = 8000) -> str:
    """Sanitize a multi-line LLM-facing block such as a tool summary or snippet.

    Same detection and redaction as `_clean_field`, but newlines are kept. Applied
    where tool summaries reach the model (`_log_tool_result` and the pre-route
    returns), so every tool's output passes through it.
    """
    if text is None:
        return ""
    text = str(text)
    if not text:
        return ""
    import unicodedata
    # Clean, structure-preserving form: NFC + drop Cc (except tab/newline) + Cf.
    nfc = unicodedata.normalize("NFC", text)
    cleaned = "".join(
        c for c in nfc if c in "\n\t" or unicodedata.category(c) not in ("Cc", "Cf")
    )
    # Detection fold: NFKC + drop Cc/Cf/Mn so mark/format-split tokens are caught.
    fold = "".join(
        c for c in unicodedata.normalize("NFKC", text)
        if c in " \t\n" or (
            unicodedata.category(c) not in ("Cc", "Cf", "Mn")
            and c not in _ZERO_WIDTH_NON_CATEGORY
        )
    )
    if _INJECTION_PATTERNS.search(fold):
        # Redact on `fold`: the ASCII regex matches only the NFKC form. `fold`
        # keeps newlines, so the redacted block stays readable.
        return _INJECTION_PATTERNS.sub("[redacted-instruction-like-text]", fold)[:max_len]
    return cleaned[:max_len]


class SemanticRetrievalPending(RuntimeError):
    """No index describes the loaded corpus.

    The on-disk index's signature does not match this database's stored vectors (or none are stored
    yet), and a question does not build one."""


#: What Genie is told, and says, while no index describes the loaded corpus.
RETRIEVAL_PENDING_NOTE = (
    "Live semantic retrieval is pending: the similarity index has not been built for the records this site serves, "
    "so no record is retrieved by meaning and no similarity neighbour is listed. The tools that read the database "
    "directly (lookup_property, database_inventory, recommend_materials, screen_candidates, material_comparison, "
    "visualize_structure and the calculation tools) are unaffected.")


class EmbeddingWriteRefused(RuntimeError):
    """A corpus embedding would be created or changed outside the offline embedding commands."""


#: Set only inside `offline_embedding_writes()`: the offline commands (`sync_material_embeddings_batch`,
#: `rebuild_faiss_index`) are the only place a MaterialEmbedding row is written or an embedding is
#: requested for a corpus material. Answering a question (`ask`, similarity) reads stored vectors only.
_OFFLINE_EMBEDDING_WRITES = contextvars.ContextVar("lamp_offline_embedding_writes", default=False)


@contextlib.contextmanager
def offline_embedding_writes():
    """Allow `EmbeddingIndexer` to embed and store corpus materials (offline commands only)."""
    token = _OFFLINE_EMBEDDING_WRITES.set(True)
    try:
        yield
    finally:
        _OFFLINE_EMBEDDING_WRITES.reset(token)


def _refuse_outside_offline_commands() -> None:
    if not _OFFLINE_EMBEDDING_WRITES.get():
        raise EmbeddingWriteRefused(
            "Material embeddings are written only by the offline embedding commands "
            "(`python -m lamp_genie embed`, then `python -m lamp_genie index`); "
            "answering a question reads the stored vectors and does not create or refresh them.")


def stored_vector(material, embedding_row=None) -> Optional[np.ndarray]:
    """The stored vector of `material` when it still describes the material, else None.

    Read only: no embedding call and no write. A missing row, an empty vector, or a vector whose
    `text_snapshot` is not the material's text today (stale) is "no vector"."""
    row = embedding_row if embedding_row is not None else (
        MaterialEmbedding.objects.filter(material=material).first())
    if row is None or not row.embedding:
        return None
    if row.text_snapshot != _build_material_text(material)[:4000]:
        return None
    return np.array(row.embedding, dtype=np.float32)


def fresh_hit_ids(stored_texts: Dict[int, str]) -> set:
    """The ids of `{material id: indexed text}` whose indexed text is the material's text today.

    An index hit carries the text its vector was embedded from (the document's page content, the
    row's `text_snapshot`). A hit whose text the material no longer has describes something else (a
    relabelled record, a changed description) and is never presented; nothing is re-embedded to
    repair it, since answering a question reads stored vectors only. Three aggregate queries for the
    batch (`with_embed_inputs`)."""
    ids = [i for i, t in stored_texts.items() if i is not None and t is not None]
    if not ids:
        return set()
    current = with_embed_inputs(Material.objects.filter(id__in=ids, **IMPORTED_ONLY))
    return {m.pk for m in current if _build_material_text(m)[:4000] == stored_texts[m.pk]}


def _doc_material_id(doc):
    raw = (getattr(doc, "metadata", None) or {}).get("material_id")
    try:
        return int(raw) if raw is not None and str(raw).strip() else None
    except (TypeError, ValueError):
        return None


def fresh_documents(documents) -> list:
    """`documents` (index hits, in order) without those whose text the material no longer has."""
    texts = {}
    for d in documents:
        mid = _doc_material_id(d)
        if mid is not None and mid not in texts:
            texts[mid] = getattr(d, "page_content", None)
    fresh = fresh_hit_ids(texts)
    return [d for d in documents if _doc_material_id(d) in fresh]


class EmbeddingIndexer:
    """Create and manage OpenAI embeddings of corpus materials."""

    def __init__(self) -> None:
        if not settings.OPENAI_API_KEY:
            raise ImproperlyConfigured("OPENAI_API_KEY is not configured.")

        # Model names come from the Django settings (`lamp_genie.configure`).
        self.embedding_model = settings.OPENAI_EMBEDDING_MODEL
        # Explicit timeout and bounded retries so a slow OpenAI call cannot hold
        # a question or an embedding batch indefinitely.
        self.client = OpenAI(
            api_key=settings.OPENAI_API_KEY,
            timeout=settings.OPENAI_REQUEST_TIMEOUT,
            max_retries=2,
        )

    def embed_text(self, text: str) -> List[float]:
        response = self.client.embeddings.create(
            model=self.embedding_model,
            input=text,
        )
        return response.data[0].embedding

    def ensure_embedding(self, material: Material) -> np.ndarray:
        _refuse_outside_offline_commands()
        embedding_obj, _ = MaterialEmbedding.objects.get_or_create(material=material)
        text = _build_material_text(material)
        snapshot = text[:4000]
        # Re-embed when there is no vector yet or the material's text changed since the
        # stored snapshot, so a relabelled record does not keep a vector of its old labels.
        if (not embedding_obj.embedding) or (embedding_obj.text_snapshot != snapshot):
            vector = self.embed_text(text)
            embedding_obj.embedding = vector
            embedding_obj.vector_size = len(vector)
            embedding_obj.text_snapshot = snapshot
            # Stored when the connection may write; on a read-only connection the fresh
            # vector is still returned instead of failing the calling tool.
            try:
                with transaction.atomic():
                    embedding_obj.save(update_fields=["embedding", "vector_size", "text_snapshot", "updated_at"])
            except DatabaseError as exc:
                logger.info("embedding of material %s not stored: %s", material.pk, exc)
        return np.array(embedding_obj.embedding, dtype=np.float32)

    def ensure_all_embeddings(self) -> int:
        """Generate missing embeddings. Returns count of failures."""
        _refuse_outside_offline_commands()
        failures = 0
        # Imported materials only: a material with a `created_by` user (none in the
        # deposit) would otherwise get a vector in the index every question searches, and
        # `_documents_to_materials` would print it into the system prompt as a
        # database record (`sync_material_embeddings_batch` applies the same scope).
        #
        # No prefetch: `_build_material_text` reads `imported_properties(material)`,
        # a fresh `.filter()` that a plain prefetch cache cannot serve, so prefetched
        # relations would be loaded and never read. `.iterator()` keeps the working
        # set bounded.
        for material in (Material.objects.filter(**IMPORTED_ONLY)
                         .iterator(chunk_size=500)):
            try:
                self.ensure_embedding(material)
            except Exception as exc:
                failures += 1
                logger.error("Embedding failed for material %s (%s): %s", material.id, material.formula, exc)
        if failures:
            logger.error("Embedding sync completed with %d failures out of %d materials", failures, Material.objects.count())
        return failures


@dataclass
class ToolResult:
    name: str
    title: str
    summary: str
    payload: Dict[str, Any]


# The Seebeck coefficient is stored under three exact names: the bulk
# Seebeck_coefficient (signed) and the carrier-resolved seebeck_p / seebeck_n
# channels (some JARVIS materials carry only the channels). A generic "seebeck"
# query covers all three by exact name, never by substring. Display prefers the
# bulk value, then the p-channel, then the n-channel.
SEEBECK_PROPERTY_NAMES = ("Seebeck_coefficient", "seebeck_p", "seebeck_n")


#: The property names a row-building tool reads for its scalar columns.
_ROW_PROPERTY_NAMES = (
    "bandgap", "HOMO", "LUMO", "formation_energy_per_atom",
    "energy_above_hull", "ZT",
    # `materials_retriever` reports this one too and reads through the same batch;
    # a name missing here becomes "no value" rather than an error, so the list is
    # the union of what every consumer prints.
    "pl_lifetime",
    # `recommend_materials` prints these too and reads through the same batch.
    "pce_estimate", "PCE", "superconducting_tc",
) + SEEBECK_PROPERTY_NAMES


def _illumination_key(spectrum: Optional[str], light: Optional[float]) -> tuple:
    """The light that decides whether two PCEs compare.

    The stated spectrum and intensity of the cell (`Device.spectrum`,
    `Device.light_intensity_mw_cm2`).

    Atmosphere (Air / N2 / Ambient / Ar / Vacuum) and temperature are not part of the key: grouping
    on them would split cells measured under the same light and understate how many cells a champion
    is compared against. The spectrum is compared case-blind.
    """
    return ((spectrum or "").strip().casefold(), light)


def _neighbour_section(faiss_result) -> str:
    """The constraint-satisfying FAISS neighbours, as text the model reads.

    Both similarity paths combine conceptual cousins with the neighbours
    `_run_similarity_tool` returns under the question's constraints. This section
    is the single rendering of those neighbours, so the model sees them alongside
    the cousin table and not only callers that read `payload["items"]`.
    """
    if faiss_result is None or not getattr(faiss_result, "summary", ""):
        return ""
    items = (faiss_result.payload or {}).get("items") if isinstance(faiss_result.payload, dict) else None
    if not items:
        return ""
    return ("NEAREST DATABASE RECORDS satisfying the question's constraints "
            "(embedding distance, independent of the cousin table above):\n"
            + _sanitize_block(faiss_result.summary, max_len=1500))


def _resolve_cousins(cousins_formulas):
    r"""Return {cousin formula: row dict}, one imported material per cousin, in batched queries.

    Shared by the similarity tool and `_pre_route_tools`. Each cousin resolves to
    its lowest-id record of the same compound; there is no digit-stripped
    fallback, since `CsPbBr` is a different compound from `CsPbBr3`. A cousin
    the corpus does not hold is absent from the result, and callers report it as
    "not in LAMP database".
    """
    first_ids = {}
    for cf in cousins_formulas or []:
        ids = _compound_ids(cf)
        if ids:
            first_ids[cf] = min(ids)
    if not first_ids:
        return {}
    mats = {m.id: m for m in Material.objects.filter(
        id__in=list(first_ids.values()), **IMPORTED_ONLY)}
    # Batched reads for band gaps and champion cells.
    by_material = _batch_property_picks(list(mats))
    _attach_champion_pools(list(mats.values()))

    out = {}
    for cf, mid in first_ids.items():
        m = mats.get(mid)
        if m is None:
            continue
        bg = _pick_lowest_pk(by_material, m.id, "bandgap")
        cell = champion_cell(m)
        out[cf] = {
            # `id` is required by callers that read `payload["items"]`.
            "id": m.id,
            "formula": m.formula,
            "data_source": m.data_source,
            "is_lead_free": m.is_lead_free,
            "chemical_class": m.chemical_class,
            "structure_type": m.structure_type,
            "dimensionality": m.dimensionality,
            "bandgap": bg["value"] if bg and bg["value"] is not None else None,
            "pce": cell.pce if cell and cell.pce is not None else None,
        }
    return out


def _attach_champion_pools(materials) -> None:
    """Give each material the bounded pool `champion_cell` would have read.

    One query for the whole list instead of one per material. `champion_cell`
    answers from `CHAMPION_POOL_ATTR` when it is present and reads the database
    otherwise; the queryset below is the same read (same filter, same
    `Coalesce("pce", 0.0).desc(), "id"` order, same CHAMPION_POOL_SIZE bound), so
    the screening logic is unchanged. Unlike an unbounded
    `prefetch_related("devices")`, it loads at most CHAMPION_POOL_SIZE rows per
    material.

    Nothing is set for a material the query does not return, so `champion_cell`
    falls back to its own read rather than seeing an empty pool.
    """
    materials = [m for m in materials if m is not None]
    if not materials:
        return
    ids = [m.pk for m in materials]
    pools = {
        m.pk: getattr(m, CHAMPION_POOL_ATTR)
        for m in Material.objects.filter(pk__in=ids).prefetch_related(
            Prefetch(
                "devices",
                queryset=champion_pool_queryset()[:CHAMPION_POOL_SIZE],
                to_attr=CHAMPION_POOL_ATTR,
            )
        )
    }
    for mat in materials:
        pool = pools.get(mat.pk)
        if pool is not None:
            setattr(mat, CHAMPION_POOL_ATTR, pool)


def _batch_property_picks(material_ids) -> Dict[int, Dict[str, List[dict]]]:
    """Every property a row needs, for a whole set of rows, in one query.

    A per-column `.first()` costs one query per column per material, and the
    `ORDER BY id LIMIT 1` Django appends makes PostgreSQL walk the primary key
    instead of the `material_id` index (seconds per read on a material with tens
    of thousands of properties). One `name__in` read over the set avoids both.
    Shared by both row-building tools, so their selection rules cannot diverge.

    Returns `{material_id: {lowercased name: [row dicts, unordered]}}`; the
    pickers impose the order they need.
    """
    by_material: Dict[int, Dict[str, List[dict]]] = {}
    material_ids = list(material_ids or [])
    if not material_ids:
        return by_material
    from materials.models import Property as _Prop
    # `icontains="homo"` reads the `HOMO` and `HOMO-LUMO_gap` rows.
    # `name__in` is case-sensitive: `name` carries the `corpus_property_name` index, so it
    # is an index scan, while a `Lower(name)` predicate has no functional index and would
    # scan the whole property table. Exact
    # names suffice because `_ROW_PROPERTY_NAMES` holds the spellings the corpus
    # stores; a row stored under another spelling would not be reported.
    _name_q = Q(name__in=_ROW_PROPERTY_NAMES) | Q(name__icontains="homo")
    # Suspect values are excluded before any picker sees them (quality.eligible_properties), so
    # a picker never chooses on a value it does not show. A warning travels with the row
    # (`quality_warning`) so the row can say so.
    from materials.models import PropertyQualityIssue as _Issue
    _warned = Exists(_Issue.objects.filter(property_id=OuterRef("pk"), severity="warning"))
    for _r in (eligible_properties(_Prop.objects
               .filter(_name_q, material_id__in=material_ids, **IMPORTED_ONLY))
               .annotate(quality_warning=_warned, phase=KT("context__phase"))
               # No ORDER BY: it forces an on-disk sort for materials with many
               # properties. The pickers order in Python.
               .order_by()
               # `unit` because consumers print it (`materials_retriever` reads
               # it for `carrier_lifetime`); `temperature_k` because the
               # recommendation applies a measurement-temperature bound to ZT
               # in Python over these rows.
               .values("material_id", "id", "name", "value", "unit", "method",
                       "reference", "data_source",
                       "temperature_k", "quality_warning", "phase")):
        (by_material.setdefault(_r["material_id"], {})
         .setdefault((_r["name"] or "").lower(), []).append(_r))
    return by_material


def _rows_for(by_material, mat_id, *names, **bounds):
    """Batched rows for these names, narrowed by an optional numeric range.

    The recommendation applies filters the batch query does not express (a
    bandgap window, a `pce_max`, a measurement-temperature floor, an
    energy-above-hull bound). The batch returns every row per name, so the same
    predicate is applied here over what came back.

    `bounds` keys are Django-shaped (`value__gte`, `temperature_k__lte`, ...)
    so a caller can pass the dict it already built for the queryset.
    """
    bucket = by_material.get(mat_id) or {}
    out = []
    for name in names:
        out.extend(bucket.get(name.lower(), []))
    for key, limit in (bounds or {}).items():
        if limit is None:
            continue
        if key == "context__phase":
            out = [r for r in out if r.get("phase") == limit]
            continue
        field, _, op = key.partition("__")
        out = [r for r in out
               if r.get(field) is not None
               and ((r[field] >= limit) if op == "gte" else (r[field] <= limit))]
    return out


def _pick_min_of(rows):
    """Return the row with the smallest value, lowest pk on ties."""
    got = [r for r in rows if r.get("value") is not None]
    return min(got, key=lambda r: (r["value"], r["id"])) if got else None


def _pick_max_of(rows):
    """Return the row with the largest value, lowest pk on ties."""
    got = [r for r in rows if r.get("value") is not None]
    return max(got, key=lambda r: (r["value"], -r["id"])) if got else None


def _pick_first_of(rows):
    """Return the row with the lowest pk."""
    return min(rows, key=lambda r: r["id"]) if rows else None


def _material_label(material) -> str:
    """How a material is named in text a model reads.

    Follows `display.material_display_label`: a StarryData2 sample reads
    "formula – sample label (DOI ...)" and a Curated-OLED compound number
    "Compound 2 (journal)". Falls back to the formula, then the name (Curated-OLED
    emitters have an empty `formula` and are identified by name, e.g. AnBNCz),
    then the external record id. `formula` in the payload still carries what the
    corpus holds, so a consumer that parses it never receives a trade name.
    """
    from materials.services.display import material_display_label
    shown = _clean_field(material_display_label(material), max_len=200)
    if shown:
        return shown
    for candidate in (getattr(material, "formula", "") or "",
                      getattr(material, "name", "") or ""):
        cleaned = _clean_field(candidate)
        if cleaned:
            return cleaned
    record = _clean_field(getattr(material, "external_id", "") or "")
    if record:
        return f"record {record}"
    return f"material {getattr(material, 'id', '?')}"


def _illumination_note(device) -> str:
    """What light a PCE was measured under, when that is not one sun.

    A PCE measured under indoor light (e.g. 0.03 mW/cm2) is not comparable with
    one under AM1.5G, so a bare value beside one-sun values would misstate it.

    The light is the cell's stated class (`Device.illumination_class`,
    device_policy): a one-sun cell gets no annotation; a cell under another stated
    light says which (its condition as displayed, else its spectrum and
    intensity); a cell whose source states no light says so, which is not the
    same as one sun. `device` is a Device or a mapping with the same keys.
    """
    from materials.services.device_policy import ONE_SUN_CLASS, OTHER_ILLUMINATION_CLASS

    def get(key):
        return device.get(key) if isinstance(device, dict) else getattr(device, key, None)

    if device is None:
        return "illumination not recorded"
    illumination = get("illumination_class")
    if illumination == ONE_SUN_CLASS:
        return ""
    if illumination == OTHER_ILLUMINATION_CLASS:
        stated = _clean_field(get("test_condition") or "", max_len=120).strip()
        if not stated:
            light = get("light_intensity_mw_cm2")
            stated = "; ".join(x for x in (_clean_field(get("spectrum") or "", max_len=60),
                                           f"{_format_measurement(light)} mW/cm²" if light is not None else "") if x)
        return f"measured at {stated}" if stated else "measured under a light other than one sun"
    return "illumination not recorded"


def _select_zt(by_material, mat_id):
    """Return the material's peak ZT row.

    ZT rows are often points of a digitized temperature curve, so the lowest-pk
    row is merely the first point. Every tool reports the peak through this helper.
    """
    return _pick_max_of((by_material.get(mat_id) or {}).get("zt", []))


def _population_clause(rows, *, selected="one", unit=None, decimals=3):
    """Format a clause such as `(peak of 32 imported values, 0.140 to 0.841, over 100.0-866.2 K)`.

    Empty for fewer than two values. Count and range come from the same rows
    (those with a value). The temperature span is added only when more than one
    temperature is recorded; a single one is shown on the provenance line.
    """
    values = [r["value"] for r in rows if r.get("value") is not None]
    if len(values) < 2:
        return ""
    lo, hi = min(values), max(values)
    out = (f" ({selected} of {len(values)} imported values, "
           f"{lo:.{decimals}f} to {hi:.{decimals}f}"
           + (f" {unit}" if unit else ""))
    temps = {r["temperature_k"] for r in rows
             if r.get("value") is not None and r.get("temperature_k") is not None}
    if len(temps) > 1:
        out += f", over {min(temps):.1f}-{max(temps):.1f} K"
    return out + ")"


def _pick_lowest_pk(by_material, mat_id, *names):
    """Return the lowest-pk row of the first name that has any rows."""
    bucket = by_material.get(mat_id) or {}
    for name in names:
        got = bucket.get(name.lower())
        if got:
            return min(got, key=lambda r: r["id"])
    return None


def _pick_min_value(by_material, mat_id, name):
    """Return the row with the smallest value, lowest pk on ties.

    The pk tie-break makes the reported method and reference deterministic
    when several rows share the minimum.
    """
    rows_ = [r for r in (by_material.get(mat_id) or {}).get(name.lower(), [])
             if r["value"] is not None]
    if not rows_:
        return None
    return min(rows_, key=lambda r: (r["value"], r["id"]))


def _pick_contains(by_material, mat_id, needle):
    """Return the lowest-pk row across every name containing `needle`."""
    bucket = by_material.get(mat_id) or {}
    hits = [r for key, rows_ in bucket.items() if needle in key for r in rows_]
    return min(hits, key=lambda r: r["id"]) if hits else None


#: The words a question uses for each range-filter property, for the window
#: and quantifier rules that are stated once for all of them. Keys are the
#: `_RANGE_FILTERS` keys; the text has already had "band gap" folded to
#: "bandgap".
_WINDOW_PROPERTY_WORDS = (
    ("bandgap", r"bandgaps?"),
    ("homo_lumo", r"homo[-\s]?lumo(?:\s+gaps?)?"),
    ("pce", r"pces?|power\s+conversion\s+efficienc(?:y|ies)|efficienc(?:y|ies)"),
    ("zt", r"zts?|figures?\s+of\s+merit"),
    ("seebeck", r"seebeck(?:\s+coefficients?)?"),
    ("mobility", r"mobilit(?:y|ies)"),
    ("carrier_lifetime", r"(?:carrier\s+)?lifetimes?"),
    ("stability", r"energ(?:y|ies)\s+above\s+(?:the\s+)?(?:convex\s+)?hull|e_hull"),
    ("tc", r"tcs?|critical\s+temperatures?"),
)

#: Every numeric range a recommendation can be narrowed by, as
#: (filter_params prefix, relation, extra lookups on that relation).
#: One table shared by the agent tool and the pre-router, so both paths apply
#: the same bounds to the same question.
_RANGE_FILTERS = (
    ("bandgap", "property", {"name__iexact": "bandgap"}),
    ("homo_lumo", "property", {"name__iexact": "HOMO-LUMO_gap"}),
    ("pce", "pce", {}),                      # device OR property; see below
    # the stored names (`pl_lifetime`: Curated-Perovskite's and Curated-OLED's PL lifetime in ns;
    # `carrier_mobility`: StarryData2)
    ("carrier_lifetime", "property", {"name__iexact": "pl_lifetime"}),
    ("mobility", "property", {"name__iexact": "carrier_mobility"}),
    # energy_above_hull, not the whole category="stability" bucket, which mixes
    # eV/atom energies with hour-scale device lifetimes.
    ("stability", "property", {"name__iexact": "energy_above_hull"}),
    ("zt", "property", {"name__iexact": "ZT"}),
    ("seebeck", "property", {"name__in": SEEBECK_PROPERTY_NAMES}),
    ("tc", "property", {"name__iexact": "superconducting_tc"}),
)



