#: The chemical words a family is named by, mapped onto the token a formula
#: spells them with.
#:
#: A family question states its members by name ("caesium lead bromide-iodide
#: perovskites", "with both lead and tin on the B site"); each named constituent
#: becomes a required formula token.
#:
#: Site-agnostic: a formula does not record which site a constituent occupies,
#: so "both lead and tin on the B site" is enforced as the formula containing
#: Pb and Sn. Stating the site narrows nothing further.
_COMPOSITION_WORDS = {
    # A-site organics and alkali cations
    "formamidinium": "FA", "methylammonium": "MA", "caesium": "Cs",
    "cesium": "Cs", "rubidium": "Rb", "potassium": "K", "sodium": "Na",
    "guanidinium": "GA", "phenethylammonium": "PEA", "butylammonium": "BA",
    "ethylammonium": "EA", "dimethylammonium": "DMA",
    # B-site metals
    "lead": "Pb", "tin": "Sn", "germanium": "Ge", "bismuth": "Bi",
    "antimony": "Sb", "silver": "Ag", "copper": "Cu", "titanium": "Ti",
    "zinc": "Zn", "molybdenum": "Mo", "tungsten": "W", "iron": "Fe",
    "nickel": "Ni", "cobalt": "Co", "manganese": "Mn", "indium": "In",
    "gallium": "Ga", "aluminium": "Al", "aluminum": "Al", "zirconium": "Zr",
    "hafnium": "Hf", "yttrium": "Y", "europium": "Eu", "terbium": "Tb",
    # X-site anions, in both the "-ide" and the element spelling
    "iodide": "I", "iodine": "I", "bromide": "Br", "bromine": "Br",
    "chloride": "Cl", "chlorine": "Cl", "fluoride": "F", "fluorine": "F",
    "oxide": "O", "oxygen": "O", "sulfide": "S", "sulphide": "S",
    "sulfur": "S", "selenide": "Se", "selenium": "Se", "telluride": "Te",
    "tellurium": "Te", "nitride": "N", "nitrogen": "N", "phosphide": "P",
    "arsenide": "As", "carbide": "C", "hydride": "H",
}

#: The cation tokens a "mixed-cation" member would carry a second of, and the
#: halide tokens a "mixed-halide" member would. "The family excludes
#: mixed-cation and mixed-halide members" needs the set it excludes from.
_CATION_TOKENS = ("FA", "MA", "Cs", "Rb", "K", "Na", "GA", "PEA", "BA",
                  "EA", "DMA")
_HALIDE_TOKENS = ("I", "Br", "Cl", "F")
#: The metals a family names its B site by, read like the other two vocabularies:
#: "the methylammonium lead iodides" do not include the lead-tin alloys.
_B_SITE_TOKENS = ("Pb", "Sn", "Ge", "Bi", "Sb", "Ag", "Cu", "Ti", "Zn", "Mo",
                  "W", "Fe", "Ni", "Co", "Mn", "In", "Ga", "Al", "Zr", "Hf")

#: Longest first so "methylammonium" is read before "ammonium" would be, and so
#: a two-word spelling wins over either of its words.
_COMPOSITION_WORD_RE = re.compile(
    r"(?<![a-z])(" + "|".join(
        re.escape(word) for word in
        sorted(_COMPOSITION_WORDS, key=len, reverse=True)
    ) + r")(?![a-z])", re.IGNORECASE)

#: Words allowed inside a run of constituents without breaking it. A family is
#: written "caesium lead bromide-iodide", or "both lead and tin", or spelled
#: site by site -- "formamidinium on the A site, tin on the B site and bromide
#: on the X site". The joiners and site phrases are not new subjects; without
#: them each constituent would stand alone, and a run of one is a class, not a
#: family.
_COMPOSITION_JOINERS = frozenset({
    "and", "both", "or", "with", "on", "the", "site", "sites", "a", "b", "x",
    "alone", "only", "solely", "purely",
})


def composition_tokens(text: str) -> List[str]:
    """Return the constituent tokens a family is named by, in order, without duplicates.

    Only runs of two or more consecutive chemical words count; a single word
    ("oxide materials") names a chemical class, not a composition family.
    """
    if not text:
        return []
    matches = list(_COMPOSITION_WORD_RE.finditer(text))
    tokens: List[str] = []
    run: List[str] = []
    alternatives = False
    previous_end = None

    def _close(run, alternatives):
        # A run joined by "or" lists alternatives, not constituents
        # ("methylammonium, formamidinium or caesium on the A site").
        return run if len(run) >= 2 and not alternatives else []

    for match in matches:
        token = _COMPOSITION_WORDS[match.group(1).lower()]
        if previous_end is not None:
            between = text[previous_end:match.start()]
            words = re.findall(r"[a-z]+", between.lower())
            joined = all(word in _COMPOSITION_JOINERS for word in words)
            # A run survives separators, joiners and hyphens; any other word
            # ("perovskites", "records", "from") ends it.
            if not joined or len(between) > 40:
                tokens.extend(_close(run, alternatives))
                run, alternatives = [], False
            elif "or" in words:
                alternatives = True
        run.append(token)
        previous_end = match.end()
    tokens.extend(_close(run, alternatives))
    ordered: List[str] = []
    for token in tokens:
        if token not in ordered:
            ordered.append(token)
    return ordered


def _letters_that_would_make_it_a_cation(token: str) -> str:
    """Return the letters a one-letter symbol may not be followed by.

    Organic cations are written in capitals, so the F of FAPbBr3 would otherwise
    read as fluorine. Derived from `_CATION_TOKENS`; shared by the membership
    test and the coefficient reader so both agree.
    """
    return "".join(sorted({
        cation[1] for cation in _CATION_TOKENS
        if len(token) == 1 and len(cation) > 1
        and cation[0] == token and cation[1].isupper()
    }))


#: A constituent in a formula, with the coefficient that follows it.
_COEFFICIENT_RE = {
    token: re.compile(
        rf"{re.escape(token)}(?![a-z{_letters_that_would_make_it_a_cation(token)}])"
        r"(\d*\.?\d*)")
    for token in _HALIDE_TOKENS
}


def halide_site_total(formula: str) -> Optional[float]:
    """Return the total halide coefficient of the formula (its X-site count), or None.

    The structure_type label cannot distinguish ABX3 from vacancy-ordered A2BX6
    (Cs2SnI6 is stored as "Perovskite"); the X-site sum does (3 against 6), and a
    mixed halide such as CsPbBr0.15I2.85 still totals 3.
    """
    total = 0.0
    seen = False
    for token, pattern in _COEFFICIENT_RE.items():
        for match in pattern.finditer(formula or ""):
            seen = True
            raw = match.group(1)
            total += float(raw) if raw not in ("", ".") else 1.0
    return total if seen else None


def _composition_boundary_pattern(token: str) -> str:
    """Return a regex matching a constituent at a chemical-symbol boundary.

    The boundary is on the right only: "I" is iodine when the next character is
    not lowercase (not In or Ir), and "C" is not the C of Cs. A left-hand guard
    would miss Pb in CsPbBr3, where a lowercase letter precedes it. A one-letter
    symbol also may not be followed by the letter that makes it an organic cation
    (F not by A, as in FA). Written as a character class rather than a lookahead
    so it behaves the same on every database backend.
    """
    banned = _letters_that_would_make_it_a_cation(token)
    return rf"{re.escape(token)}(?:[^a-z{banned}]|$)"


def _classification_matchers():
    """Return (pattern, column, value) matchers, longest value first.

    Longest first so "Curated-Perovskite" is read as the source it is rather
    than as the "Perovskite" inside it. Separators are flexible for the same
    reason property names need it -- people write "solar-cell" and "solar cell"
    -- and a trailing plural is allowed.
    """
    entries = [
        (column, value, value)
        for column, values in CORPUS_CLASSIFICATION.items()
        for value in values
    ]
    entries += [
        (column, stored, alias)
        for column, aliases in CLASSIFICATION_ALIASES.items()
        for stored, spellings in aliases.items()
        for alias in spellings
    ]
    # "the perovskite-structure materials" names the same structure_type as
    # "perovskites", but the bare value's pattern refuses a neighbouring hyphen
    # -- the guard that keeps "Curated-Perovskite" from reading as "Perovskite".
    # Derived from the vocabulary rather than hand-listed so a new structure
    # type gets the compound spellings for free, and longer than the bare value
    # so it wins the longest-first ordering.
    entries += [
        ("structure_type", value, f"{value} {suffix}")
        for value in CORPUS_CLASSIFICATION["structure_type"]
        for suffix in ("structure", "structures", "type")
    ]
    # By the length of the spelling being matched, so "Materials Project" is
    # tried before "MP" and "Curated-Perovskite" before "Perovskite".
    entries.sort(key=lambda entry: (-len(entry[2]), entry[0], entry[2]))
    matchers = []
    for column, stored, spelling in entries:
        tokens = [re.escape(token) for token in re.split(r"[\s_\-]+", spelling)]
        pattern = r"[\s_\-]+".join(tokens)
        # A Korean spelling takes a particle, so Hangul may follow it.
        tail = r"(?![A-Za-z0-9_-])" if re.search(r"[\uac00-\ud7a3]", spelling) else r"s?(?![\w-])"
        matchers.append(
            (re.compile(rf"(?<![\w-]){pattern}{tail}", re.IGNORECASE),
             column, stored)
        )
    return tuple(matchers)


CLASSIFICATION_MATCHERS = _classification_matchers()


def _median_of(values: Sequence[float]) -> float:
    """Median of an already-sorted sequence."""
    n = len(values)
    mid = n // 2
    return values[mid] if n % 2 else (values[mid - 1] + values[mid]) / 2


#: Organic-cation tokens the platform writes inside formulas (distinct from `_CATION_TOKENS`,
#: the A-site list the selection filters read).
_ORGANIC_CATION_TOKENS = ("PEA", "PPA", "FA", "MA", "EA", "GA", "BA", "PA")


def is_element_symbol(token: str) -> bool:
    """Return True if `token` is a real element symbol, not merely element-shaped."""
    from materials.services.analysis_tools import FormulaValidator
    return bool(re.fullmatch(r"[A-Z][a-z]?", token or "")) and token in FormulaValidator._KNOWN_ELEMENTS


def question_plan(text: str, history: Sequence[str] = ()):
    """Parse `text` into a `question_conditions.QuestionPlan` using the corpus vocabulary.

    `history` is the earlier user messages, oldest first."""
    from .question_conditions import parse_question
    return parse_question(text or "", property_patterns=PROPERTY_NAME_PATTERNS, is_element=is_element_symbol,
                          sources_in=lambda text: sources_named_in(text, fuzzy=True), history=list(history or ()),
                          cation_tokens=_ORGANIC_CATION_TOKENS + ("Cs", "Rb", "K"))


